// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public {
        c = new SimpleWallet();
        vm.deal(address(c), 10 ether);
    }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= address(c).balance);
        vm.assume(amount > 0);

        bool success;
        try c.withdraw(amount) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(!success, "Withdraw must revert when transfer to non-payable owner fails");
    }
}
